//go:build !purego

package tensor

// ASIMD (NEON) is mandatory on every arm64 CPU Go supports, so the kernel
// needs no feature check.
var neonKernel = &microkernel{
	id: KernelNEON, mr: 8, nr: 8,
	blockM: 64, blockN: 32,
	f32: neonF32, q8: neonQ8,
}

func archMicrokernel() *microkernel { return neonKernel }

// neonF32 and neonQ8 are generated by ./asmgen; see microkernel for the
// contract. The int8 variant sign-extends and converts each packed weight in
// registers before the multiply-add.
//
//go:noescape
func neonF32(kc int, a *float32, lda int, b *float32, c *float32, acc int)

//go:noescape
func neonQ8(kc int, a *float32, lda int, b *int8, c *float32, acc int)
